{
  "name": "Aged, Blind and Disabled (ABD) Medicaid",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "summary": "North Dakota’s ABD Medicaid is for people who are age 65+, blind, or disabled under Social Security standards. Income is assessed monthly and must be within the state’s Medicaid income standard for the family size; North Dakota’s published ABD income levels are updated periodically. One state source says the decision is based on whether monthly income is within the current Medicaid income levels, and another indicates a 45-day decision timeline for applications. The search results do not provide a complete official 2026 household-size table from the state page itself, but a 2026 summary of North Dakota’s ABD levels reported $1,197/month for one person, $1,623 for two, $2,049 for three, and $2,475 for four, plus $426 for each additional person, effective April 1, 2026.",
      "table": [
        {
          "household_size": 1,
          "monthly_income_limit": "$1,197"
        },
        {
          "household_size": 2,
          "monthly_income_limit": "$1,623"
        },
        {
          "household_size": 3,
          "monthly_income_limit": "$2,049"
        },
        {
          "household_size": 4,
          "monthly_income_limit": "$2,475"
        },
        {
          "household_size": "each additional person",
          "monthly_income_limit": "+$426"
        }
      ],
      "note": "North Dakota Medicaid eligibility pages state that income levels change each year and that applicants must meet the monthly income level for their family size."
    },
    "asset_limits": {
      "summary": "Countable assets must be below the North Dakota Medicaid limit for aged, blind, or disabled applicants.",
      "limits": {
        "single_person": "$3,000",
        "couple": "$6,000",
        "additional_person": "+$25 per member of the unit above two"
      },
      "what_counts": [
        "checking and savings accounts",
        "certificates of deposit",
        "stocks",
        "bonds",
        "other countable assets"
      ],
      "what_is_exempt": [
        "The search results confirm some assets are excluded, but do not provide a full official exemption list on the retrieved pages.",
        "For a complete exemption list, the North Dakota Medicaid policy manual is referenced in the search results."
      ]
    },
    "other_requirements": [
      "Must be a resident of North Dakota",
      "Must be a U.S. citizen or qualified noncitizen",
      "Must be age 65 or older, blind, or disabled using Social Security Administration standards",
      "Must be within the state’s monthly income standard",
      "Must have countable assets below the state limit",
      "Proof of assets is required for people who are blind, disabled, or age 65 and older"
    ]
  },
  "benefits": {
    "type": "service",
    "value": "ABD Medicaid provides Medicaid health coverage; the retrieved state sources do not list a dollar value, hour cap, or single fixed benefit package for all members. The program is the gateway to Medicaid coverage for older adults and people who are blind or disabled, and can also be the eligibility basis for related support such as Basic Care Assistance Program (BCAP).",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online: North Dakota HHS self-service portal at the state's Medicaid application page",
      "Paper form: Health Care Application for the Elderly and Disabled (SFN 958)",
      "Mail: request and submit a paper application through the Customer Support Center or local human service zone office",
      "Phone: Customer Support Center at (866) 614-6005 or 701-328-1000; 711 (TTY)",
      "In person: human service zone office"
    ],
    "processing_time": "A decision is made within 45 days from the date the local Human Service Zone office or the Medical Services Division receives a paper or online application with electronic signature.",
    "waitlist": null,
    "forms": [
      "Health Care Application for the Elderly and Disabled (SFN 958)",
      "Application for Assistance for Medicaid (health care) coverage"
    ],
    "documents": [
      "Proof of monthly income (pay stubs, tax return if self-employed, pension, disability payments, etc.)",
      "Proof of assets (checking and savings statements, certificates of deposit, etc.)",
      "Identity and residency documentation as needed for eligibility verification",
      "Citizenship or qualified noncitizen documentation as needed",
      "Any disability or blindness verification if not already clear from Social Security or program records"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Statewide North Dakota Medicaid eligibility; no county-only restriction was identified in the retrieved sources.",
    "regional_variations": "The core eligibility rules are statewide. Application handling is through local human service zone offices, so practical differences may show up in office access and local processing logistics rather than eligibility rules.",
    "offices_or_providers": [
      "North Dakota Human Service Zone offices",
      "North Dakota Health and Human Services Customer Support Center"
    ]
  },
  "official_source": "https://www.hhs.nd.gov/healthcare/medicaid",
  "gotchas": [
    "ABD Medicaid in North Dakota is not just age-based; applicants must also meet asset rules and monthly income rules.",
    "Assets matter for people who are blind, disabled, or age 65 and older, even if they are not usually emphasized in expansion Medicaid programs.",
    "The program uses a separate elderly/disabled paper application path (SFN 958), not just the general Medicaid application.",
    "A Medicaid application and a service application can both be part of the process for related long-term-care-like services under state rules.",
    "The state’s income standards change over time, so families should verify the current table before applying.",
    "Proof of assets is specifically required for elderly, blind, or disabled applicants.",
    "Basic Care Assistance Program coverage depends on first qualifying for North Dakota Medicaid, so ABD Medicaid is often the gatekeeper."
  ],
  "data_shape_notes": "This program is statewide and eligibility is shaped by age/disability status plus both income and asset tests. The main data structure is not household-based benefit scaling; it is a categorical Medicaid eligibility program with separate elderly/disabled application routing and a 45-day decision clock."
}

{
  "name": "Medicare Savings Programs",
  "eligibility": {
    "age": null,
    "income_limits": {
      "summary": "North Dakota uses monthly income limits for Medicare Savings Programs, with separate tiers for QMB, SLMB, and QI. The state source shows a Medicare Savings Program income limit table of $1,816 for a single person and $2,455 for a couple, and North Dakota materials indicate the program uses the federal MSP tiers under those caps.[1][4][9]",
      "tier_table": [
        {
          "tier": "QMB (Qualified Medicare Beneficiary)",
          "single_monthly_income": "Up to $1,350",
          "couple_monthly_income": "Up to $1,824",
          "what_it_covers": "Pays Medicare Part A and Part B premiums and Medicare cost-sharing.",
          "source_basis": "North Dakota 2026 MSP guidance summarized in search results.[9]"
        },
        {
          "tier": "SLMB (Specified Low-Income Medicare Beneficiary)",
          "single_monthly_income": "Over $1,350 up to $1,616",
          "couple_monthly_income": "Over $1,824 up to $2,184",
          "what_it_covers": "Pays the Medicare Part B premium only.",
          "source_basis": "North Dakota 2026 MSP guidance summarized in search results.[9]"
        },
        {
          "tier": "QI (Qualifying Individual)",
          "single_monthly_income": "Over $1,616 up to $1,816",
          "couple_monthly_income": "Over $2,184 up to $2,455",
          "what_it_covers": "Pays the Medicare Part B premium only; first-come, first-served.",
          "source_basis": "North Dakota 2026 MSP guidance summarized in search results.[9]"
        }
      ],
      "household_size_variation": "The available North Dakota figures in the search results are for single and couple households; North Dakota uses those two-person categories in its MSP asset and income references.[1][2][3][9]"
    },
    "asset_limits": {
      "limit": "North Dakota ties MSP asset eligibility to the Medicare Part D Low Income Subsidy resource standard, which changes annually. For January 2026, the limits shown are $9,950 for one person and $14,910 for two people.[2][3][8]",
      "what_counts": "Countable or non-excluded assets; North Dakota says eligibility exists only if the total value of all non-excluded assets is at or below the applicable limit.[2][8][13]",
      "what_is_exempt": "The guidebook excerpt says not to include one vehicle, your home, clothing, or household goods when assessing savings and other assets.[13]",
      "important_note": "North Dakota policy says eligibility may exist in a month when countable assets are within the limit for at least one day of the month.[2]"
    },
    "other_requirements": [
      "Must be eligible for Medicare Part A, including premium-free Part A or premium Part A.[13]",
      "Must be enrolled in Medicare and seeking help with Medicare costs rather than general Medicaid long-term-care coverage.[1][9]",
      "QI is limited by available funding and can be first-come, first-served.[9]",
      "North Dakota administers the program through county social services offices / Human Service Zone offices.[1][9]"
    ]
  },
  "benefits": {
    "type": "financial",
    "value": "Depending on tier, the program may pay Medicare Part A premiums, Part B premiums, annual deductibles, and coinsurance costs. QMB is the broadest tier and can pay Part A and Part B premiums plus Medicare cost-sharing; SLMB and QI pay the Part B premium only.[1][9]",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Apply through your county social services office / Human Service Zone office.[1][9]",
      "Use North Dakota HHS online application options for Medicaid and Medicare Savings Programs.[12]",
      "Request help or an application by phone at 1-866-614-6005 or 701-328-1000 (TTY 711 is referenced in a North Dakota-related source).[9][14]"
    ],
    "processing_time": "No official processing-time estimate appeared in the gathered sources.",
    "waitlist": "No waitlist is described for QMB or SLMB. QI is limited and first-come, first-served, so it can effectively function like a funding-limited program.[9]",
    "forms": [
      "No specific form number was identified in the gathered sources.",
      "North Dakota HHS states that applicants can apply online for Medicare Savings programs through its general medical assistance application pathway.[12]"
    ],
    "documents": [
      "Proof of Medicare Part A or Medicare enrollment.[13]",
      "Proof of monthly income such as Social Security, pension, wages, veterans benefits, or similar income sources.[13]",
      "Proof of savings and other assets, if requested.[13]",
      "Information on vehicles, home ownership, and household resources, even though some items are excluded from the asset test.[13]",
      "Identification and contact information for the applicant and spouse, if applicable."
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Statewide North Dakota program; applications are handled through county social services / Human Service Zone offices rather than a single centralized office.[1][9]",
    "regional_variations": "No benefit differences by region were identified. The main variation is administrative: families apply through their local county office, and processing speed may differ by office, but no official regional wait-time breakdown was found.",
    "offices_or_providers": [
      "County social services offices / Human Service Zone offices across North Dakota.[1][9]",
      "North Dakota Department of Health and Human Services online medical assistance application page.[12]"
    ]
  },
  "official_source": "https://www.insurance.nd.gov/consumers/medicare/medicare-financial-assistance-programs",
  "gotchas": [
    "The program is not the same as full Medicaid; it is specifically help with Medicare premiums and, for QMB, Medicare cost-sharing.[1][9]",
    "The asset limit changes annually because North Dakota ties it to the federal Medicare Part D Low Income Subsidy standard.[2][8][13]",
    "QI is not guaranteed if funding runs out because it is first-come, first-served.[9]",
    "Some resources are excluded, including the home, one vehicle, clothing, and household goods, so families should not assume all assets count.[13]",
    "Eligibility can exist for a month if countable assets are within the limit for at least one day of that month.[2]",
    "Families often miss that Medicare Part A eligibility is required before MSP can help.[13]"
  ],
  "data_shape_notes": "This program has tiered benefits and tiered income limits rather than one single standard. The asset test is tied to a separate federal resource benchmark that changes yearly, and one tier (QI) is funding-limited and first-come, first-served.[2][3][9]"
}
